"""Prospective public sensitivity to word position, holding exact lengths fixed."""
import hashlib,json,random,sys
from collections import Counter,defaultdict
from pathlib import Path

ROOT=Path(__file__).resolve().parent
REPO=ROOT.parent/'edge-cmi-current'
sys.path.insert(0,str(REPO))
import vs
vs.ROOT=str(ROOT.parent/'voynich-swarm')
from vs import corpus,dsl,generators,ivtff

FACT=ROOT.parent/'edge-cmi-preparation/staged/experiments/P-L2-020/Pavlenko77/fact.json'
PLAN={
 'question':'Does adjacent edge association survive a null preserving exact word lengths AND coarse line positions?',
 'metric':'Unchanged edge_length_cmi: I(last glyph; next first glyph | exact left/right EVA-basic lengths), weighted by adjacent-pair count.',
 'primary_null':'Permute certain nonempty P words only within (original line, exact EVA-basic length, original role) cells.',
 'roles':'singleton if n=1; initial if k=0; final if k=n-1; medial otherwise. k and n from the literal original line, before filtering.',
 'baseline_null':'Same permutation without role conditioning, reproducing PR673.',
 'sample':'34 public practice evaluation pages, separately ZL and IT; already used in prior analyses, not new independent pages.',
 'replicates':199,'seed':408,'alpha':.01,
 'decision':'Residual association supported only if primary one-sided plus-one p<=.01 in both editions, >=30 pairs are potentially movable and permuted statistic is not constant. Report all baseline and position-aware outcomes; no seed or threshold tuning.',
 'controls':[{'generator':'G-line-chain','seed':4,'order':4},{'generator':'unigram','seed':221}],
 'limits':'Coarse word role, not exact ordinal, x coordinate, glyph position within word, or physical word spacing. One fixed seed per generator. Public sensitivity only; original fact bytes remain unchanged.',
 'fact_sha256':hashlib.sha256(FACT.read_bytes()).hexdigest()}

def role(t):
    return 'singleton' if t['n']==1 else 'initial' if t['k']==0 else 'final' if t['k']==t['n']-1 else 'medial'

def groups(ts,position):
    result=defaultdict(list)
    for i,t in enumerate(ts):
        if t['unit']=='P' and not ivtff.uncertain(t['w']) and dsl.SEG(t['w']):
            key=(t['line'],len(dsl.SEG(t['w'])))
            result[key+(role(t),) if position else key].append(i)
    return list(result.values())

def permute(ts,gs,rng):
    words=[t['w'] for t in ts]
    for g in gs:
        ws=[words[i] for i in g];rng.shuffle(ws)
        for i,w in zip(g,ws):words[i]=w
    return [dict(t,w=w) for t,w in zip(ts,words)]

def invariants(ts,sh,position):
    for a,b in zip(ts,sh):
        assert {k:v for k,v in a.items() if k!='w'}=={k:v for k,v in b.items() if k!='w'}
        assert len(dsl.SEG(a['w']))==len(dsl.SEG(b['w']))
        if a['unit']!='P' or ivtff.uncertain(a['w']) or not dsl.SEG(a['w']):assert a['w']==b['w']
        if position and role(a)!='medial':assert a['w']==b['w']
    def inventory(tokens):
        return Counter((t['line'],len(dsl.SEG(t['w'])),role(t) if position else '',t['w']) for t in tokens)
    assert inventory(ts)==inventory(sh)

def run(pages):
    ts=dsl.tokens(pages)
    selected=dsl.select(ts,{'unit':['P'],'certain':True})
    statistic={'edge_length_cmi':True}
    observed=dsl.statistic(statistic,selected,ts)
    pairs=dsl._edge_length_pairs(selected)
    result={'observed_bits':observed,'pages':len(pages),'adjacent_pairs':len(pairs),'nulls':{}}
    for position in (False,True):
        gs=groups(ts,position)
        mutable={i for g in gs if len({ts[j]['w'] for j in g})>1 for i in g}
        spots={(ts[i]['line'],ts[i]['k']) for i in mutable}
        movable=sum((a['line'],a['k']) in spots or (b['line'],b['k']) in spots for a,b in pairs)
        rng=random.Random(PLAN['seed']);values=[]
        for i in range(PLAN['replicates']):
            sh=permute(ts,gs,rng)
            if i==0:invariants(ts,sh,position)
            values.append(dsl.statistic(statistic,dsl.select(sh,{'unit':['P'],'certain':True}),sh))
        p=(1+sum(v>=observed for v in values))/(len(values)+1)
        nonconstant=any(abs(v-observed)>1e-12 for v in values)
        result['nulls']['length_position' if position else 'length']={
            'p':p,'null_mean':sum(values)/len(values),'null_min':min(values),'null_max':max(values),
            'excess_over_null_mean':observed-sum(values)/len(values),
            'movable_pairs':movable,'movable_pair_share':movable/len(pairs),
            'nonconstant':nonconstant,'passes':movable>=30 and nonconstant and p<=PLAN['alpha'],
            'first_shuffle_invariants_passed':True,'permutation_values':values}
    return result

def selfcheck():
    from vs.ivtff import Page,Line
    p=Page('fixture',0,{'I':'H','L':'A','H':'1'})
    for i,ws in enumerate([['aa','rr','oo','?','ch','a','rr'],['a'],['a','rr'],['','aa','rr','oo','aa','']]):
        p.lines.append(Line(str(i),'fixture',i,'P','0',ws,False,False))
    ts=dsl.tokens([p]);sh=permute(ts,groups(ts,True),random.Random(408));invariants(ts,sh,True)
    assert any(a['w']!=b['w'] for a,b in zip(ts,sh))
    assert [role(t) for t in ts[-6:]]==['initial','medial','medial','medial','medial','final']
    return 'Analytical role fixture: literal endpoints, singleton/two-word lines, empty/uncertain barriers, EVA ch unit, and actual interior shuffle pass.'

if __name__=='__main__':
    if '--plan' in sys.argv:
        ROOT.mkdir(exist_ok=True);(ROOT/'plan.json').write_text(json.dumps(PLAN,indent=2)+'\n',encoding='utf-8');print('Plan frozen');sys.exit()
    assert json.loads((ROOT/'plan.json').read_text())==PLAN
    report={'plan':PLAN,'selfcheck':selfcheck(),'results':{},'source_sha256':{f:hashlib.sha256((Path(vs.ROOT)/'data/raw'/f).read_bytes()).hexdigest() for f in ['ZL3b-n.txt','IT2a-n.txt']}}
    for edition in ('zl','it'):
        train,ev=corpus.split_pages('practice',edition)
        sample={'manuscript':ev,'G-line-chain':generators.g_line_chain(train,ev,seed=4,order=4)}
        pool=[w for p in train for ln in p.lines for w in ln.words if w and not ivtff.uncertain(w)]
        rng=random.Random(221);sample['unigram']=generators._shape_like(ev,lambda p,ln,i:rng.choice(pool))
        report['results'][edition]={}
        for name,pages in sample.items():
            report['results'][edition][name]=run(pages)
            print(edition,name,{k:{a:b for a,b in v.items() if a!='permutation_values'} for k,v in report['results'][edition][name]['nulls'].items()},flush=True)
            (ROOT/'results.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
    assert hashlib.sha256(FACT.read_bytes()).hexdigest()==PLAN['fact_sha256']
    report['original_fact_unchanged']=True
    (ROOT/'results.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
